sql.where:
B.SAN_CoID  = C.id
AND	B.SAN_ID = A.EIY_SANID


        AND SAN_CoName  LIKE CONCAT('%',#{value},'%')


        AND SAN_Recipient_Name  LIKE CONCAT('%',#{value},'%')


        AND EIY_ID = #{value}


        AND EIY_Tracking_Number = #{value}



    and

        EIY_Ship_Time


        EIY_Time

    BETWEEN #{staTime} and #{endTime}


    AND EIY_Evaluation_Status IN

        #{EIY_Evaluation_Status}



    AND EIY_Signing_Status IN

        #{EIY_Signing_Status}



    and  C.sales_id in

        #{sales_idArr}



    and  C.id = #{cId}
